import { motion } from "framer-motion";
import React, { useState, useRef, useContext } from "react";
import { useNavigate } from "react-router-dom";
import Tesseract from "tesseract.js";
import "../DietForm.css";
import { DietPlanContext } from './DietPlanContext';
import { doc, setDoc } from "firebase/firestore";
import { auth, db } from "./firebase";
import { useTranslation } from "react-i18next";

export default function DietForm() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { setDietPlan } = useContext(DietPlanContext);

  const [formData, setFormData] = useState({
    language: "",
    weight: "",
    height: "",
    age: "",
    gender: "",
    dailybodyactivity: "",
    preferredFoods: "",
    unpreferredFoods: "",
    fitnessGoals: "",
    fitnessGoalsOther: "",
    foodallergies: "",
    medicalhistory: "",
    pastexperience: "",
    sportactivity: "",
    sportactivityOther: "",
    budget: "",
    countryorregion: "",
    extranotes: "",
    inbodyFile: null,
    inbodyText: "",
    // New fields
    religion: "",
    religionOther: "",
    occupation: "",
    foodRecallDay1: "",
    foodRecallDay2: "",
    foodRecallDay3: "",
  });

  const inbodyTextRef = useRef("");
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleFileChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setFormData((prev) => ({ ...prev, inbodyFile: file }));

    try {
      const text = await extractTextFromImage(file);
      console.log("Extracted Text from File:", text);

      inbodyTextRef.current = text;

      setFormData((prev) => ({ ...prev, inbodyText: text }));
      return text;
    } catch (error) {
      console.error("Error extracting text from image:", error);
      return "";
    }
  };

  const extractTextFromImage = async (file) => {
    return new Promise((resolve) => {
      Tesseract.recognize(file, "eng")
        .then(({ data: { text } }) => {
          console.log("Extracted Text from Image:", text);
          resolve(text);
        })
        .catch(() => resolve(""));
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const user = auth.currentUser;
    if (!user) {
      alert(t("loginRequired"));
      setLoading(false);
      return;
    }

    const isFileUploaded = !!formData.inbodyFile;

    if (isFileUploaded && (!formData.fitnessGoals || !formData.budget)) {
      alert(t("requiredFieldsForFileUpload"));
      setLoading(false);
      return;
    }

    if (isFileUploaded) {
      try {
        console.log("Extracting text from file...");
        await handleFileChange({ target: { files: [formData.inbodyFile] } });
      } catch (error) {
        console.error("Error during text extraction:", error);
        setLoading(false);
        return;
      }
    }

    console.log("InBody Text:", inbodyTextRef.current);

    const promptText = `Act as an expert nutritionist and create a highly personalized diet plan based on the following client information:

## CLIENT PROFILE
- Basic Demographics: ${formData.age}-year-old ${formData.gender}, ${formData.height}cm, ${formData.weight}kg
- Location: ${formData.countryorregion || "Not specified"} (consider regional food availability)
- Language Preference: ${formData.language}
- Occupation: ${formData.occupation || "Not specified"}
- Religious/Dietary Restrictions: ${formData.religion === "other" ? formData.religionOther : formData.religion || "None"}

## PHYSICAL ACTIVITY ASSESSMENT
- Daily Activities: ${formData.dailybodyactivity || "Not specified"}
- Sports/Exercise: ${formData.sportactivity === "other" ? formData.sportactivityOther : formData.sportactivity || "Not specified"}

## HEALTH OBJECTIVES & CONSTRAINTS
- Primary Goal: ${formData.fitnessGoals === "other" ? formData.fitnessGoalsOther : formData.fitnessGoals}
- Medical Considerations: ${formData.medicalhistory || "None reported"}
- Food Allergies/Intolerances: ${formData.foodallergies || "None reported"}
- Past Dietary Experiences: ${formData.pastexperience || "No previous experience mentioned"}

## FOOD PREFERENCES & PRACTICALITIES
- Liked Foods: ${formData.preferredFoods || "No specific preferences"}
- Disliked/Avoidance Foods: ${formData.unpreferredFoods || "None specified"}
- Budget: ${formData.budget || "Not specified"} (provide cost-effective suggestions where applicable)
- Additional Notes: ${formData.extranotes || "None"}

## RECENT EATING PATTERNS (3-Day Food Recall)
- Day 1: ${formData.foodRecallDay1 || "Not provided"}
- Day 2: ${formData.foodRecallDay2 || "Not provided"}
- Day 3: ${formData.foodRecallDay3 || "Not provided"}

## BIOMETRIC DATA (InBody Analysis)
${inbodyTextRef.current || "Not provided"}

## REQUIREMENTS FOR THE DIET PLAN:

1. MACRONUTRIENT DISTRIBUTION:
   - Calculate appropriate calorie intake based on all provided factors including occupation (${
     formData.occupation
   }) and religious restrictions (${formData.religion === "other" ? formData.religionOther : formData.religion || "None"})
   - Provide protein, carbohydrate, and fat ratios tailored to the client's goals
   - Adjust based on activity level and body composition data if available

2. MEAL STRUCTURE:
   - Design a 7-day meal plan with breakfast, lunch, dinner, and 2 snacks
   - Include specific portion sizes in household measurements (cups, tablespoons, etc.) and metric weights
   - Provide preparation time estimates for each meal
   - Respect religious dietary restrictions: ${
     formData.religion === "other" ? formData.religionOther : formData.religion || "None"
   }

3. NUTRITIONAL CONSIDERATIONS:
   - Ensure micronutrient adequacy (vitamins and minerals)
   - Incorporate anti-inflammatory foods if appropriate
   - Include fiber recommendations based on health goals
   - Hydration plan with specific water intake recommendations

4. PERSONALIZATION ELEMENTS:
   - Adapt meals to regional cuisine of ${formData.countryorregion || "the client's region"}
   - Consider food preferences and aversions thoroughly
   - Accommodate budget constraints: ${formData.budget || "Not specified"}
   - Suggest alternatives for common allergens or restrictions
   - Consider occupation activity level: ${formData.occupation || "Not specified"}

5. IMPLEMENTATION GUIDANCE:
   - Provide practical shopping list for the week
   - Include meal prep strategies to save time
   - Suggest timing of meals around physical activities
   - Offer strategies for dining out or social occasions

6. FORMATTING:
   - Present in clear, organized sections with headings
   - Use the language: ${formData.language}
   - Include a summary table of daily nutritional targets
   - Provide rationale for key recommendations

7. EXPERT NOTES:
   - Explain how this plan addresses the specific goal of ${
     formData.fitnessGoals === "other" ? formData.fitnessGoalsOther : formData.fitnessGoals
   }
   - Note any precautions based on medical history: ${formData.medicalhistory || "None reported"}
   - Include suggestions for monitoring progress and making adjustments

IMPORTANT: 
    1- Do not mention that you are an AI. Present yourself as a nutrition expert. All recommendations must be evidence-based and personalized to this specific client's data.
    2- Do not include any statements suggesting direct contact (e.g., 'call me', 'reach out to me', 'I am here to help you personally'). Provide the diet plan only."
    3- For the introduction at the beginning of the diet plan:
       - If the language is Arabic (or country is Egypt), start with "السلام عليكم" followed by a neutral, professional message.
       - For all other languages, start with a neutral greeting like "Hello" or "Greetings" and follow with a professional introduction.
       - Do not include any personal contact suggestions or informal phrases.
    `;

    try {
      const response = await fetch(
        "https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=AIzaSyDmQ5XQV7gwYyYHwRwdSsjdDef_V-gM9Ug",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            contents: [
              {
                parts: [
                  {
                    text: promptText,
                  },
                ],
              },
            ],
          }),
        }
      );
      const data = await response.json();
      console.log("AI Response:", data);

      if (data && data.candidates && data.candidates[0]) {
        const dietPlan = data.candidates[0].content.parts[0].text;
        setDietPlan(dietPlan);

        const currentDate = new Date().toISOString().split("T")[0];
        await setDoc(
          doc(db, "users", user.uid),
          {
            dietPlan: dietPlan,
            dietPlanDate: currentDate,
          },
          { merge: true }
        );

        navigate("/DietPlan", { state: { dietPlan: data.candidates[0] } });
      } else {
        console.error("Invalid response structure:", data);
      }
    } catch (error) {
      console.error("Error generating diet plan:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className="diet-form-container flex justify-center items-center min-h-screen bg-gradient-to-r from-teal-400 to-blue-500 py-8"
      style={{ marginTop: "72px" }}
    >
      <div
        className="diet-form-card bg-white shadow-2xl rounded-xl w-full max-w-lg p-8"
        style={{ marginTop: "25px", marginBottom: "50px" }}
      >
        <h1 className="diet-form-title text-4xl font-extrabold text-center text-gray-800 mb-6">
          {t("generateYourDietPlan")}
        </h1>
        <form className="diet-form space-y-6" onSubmit={handleSubmit}>
          {/* Language */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("language")}
            </label>
            <select
              name="language"
              value={formData.language}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            >
              <option value="">{t("chooseTheLanguage")}</option>
              <option value="english">{t("english")}</option>
              <option value="arabic">{t("arabic")}</option>
              <option value="spanish">{t("spanish")}</option>
              <option value="french">{t("french")}</option>
              <option value="german">{t("german")}</option>
              <option value="italian">{t("italian")}</option>
              <option value="portuguese">{t("portuguese")}</option>
            </select>
          </motion.div>

          {/* Weight */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("weightKg")}
            </label>
            <input
              type="number"
              name="weight"
              placeholder={t("enterYourWeight")}
              value={formData.weight}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Height */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("heightCm")}
            </label>
            <input
              type="number"
              name="height"
              placeholder={t("enterYourHeight")}
              value={formData.height}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Age */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("age")}
            </label>
            <input
              type="number"
              name="age"
              placeholder={t("enterYourAge")}
              value={formData.age}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Gender */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("gender")}
            </label>
            <select
              name="gender"
              value={formData.gender}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            >
              <option value="">{t("chooseYourGender")}</option>
              <option value="male">{t("male")}</option>
              <option value="female">{t("female")}</option>
            </select>
          </motion.div>

          {/* Daily Body Activity */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("dailybodyactivity")}
            </label>
            <input
              type="text"
              name="dailybodyactivity"
              value={formData.dailybodyactivity}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Occupation */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("occupation")}
            </label>
            <input
              type="text"
              name="occupation"
              value={formData.occupation}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Country or Region */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("countryorregion")}
            </label>
            <input
              type="text"
              name="countryorregion"
              value={formData.countryorregion}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Fitness Goals */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("fitnessGoals")}
            </label>
            <select
              name="fitnessGoals"
              value={formData.fitnessGoals}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            >
              <option value="">{t("chooseYourFitnessGoal")}</option>
              <option value="muscle_gain">{t("muscleGain")}</option>
              <option value="weight_loss">{t("weightLoss")}</option>
              <option value="maintenance">{t("maintenance")}</option>
              <option value="weight_gain">{t("weightGain")}</option>
              <option value="improve_strength">{t("improvingStrength")}</option>
              <option value="boosting_energy">{t("boostingEnergy")}</option>
              <option value="faster_recovery">{t("fasterRecovery")}</option>
              <option value="improving_heart_health">{t("improvingHeartHealth")}</option>
              <option value="boosting_immune_system">{t("boostingImmuneSystem")}</option>
              <option value="enhancing_focus_and_brain">{t("enhancingFocusAndBrain")}</option>
              <option value="other">{t("other")}</option>
            </select>
            {formData.fitnessGoals === "other" && (
              <input
                type="text"
                name="fitnessGoalsOther"
                placeholder={t("specifyFitnessGoal")}
                value={formData.fitnessGoalsOther}
                onChange={handleChange}
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300 mt-2"
              />
            )}
          </motion.div>

          {/* Sport Activity */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("sportActivity")}
            </label>
            <select
              name="sportactivity"
              value={formData.sportactivity}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            >
              <option value="">{t("chooseSportActivity")}</option>
              <option value="none">{t("none")}</option>
              <option value="walking">{t("walking")}</option>
              <option value="running">{t("running")}</option>
              <option value="cycling">{t("cycling")}</option>
              <option value="swimming">{t("swimming")}</option>
              <option value="weight_training">{t("weightTraining")}</option>
              <option value="yoga">{t("yoga")}</option>
              <option value="pilates">{t("pilates")}</option>
              <option value="crossfit">{t("crossfit")}</option>
              <option value="hiking">{t("hiking")}</option>
              <option value="football">{t("football")}</option>
              <option value="basketball">{t("basketball")}</option>
              <option value="tennis">{t("tennis")}</option>
              <option value="badminton">{t("badminton")}</option>
              <option value="boxing">{t("boxing")}</option>
              <option value="martial_arts">{t("martialArts")}</option>
              <option value="dancing">{t("dancing")}</option>
              <option value="gymnastics">{t("gymnastics")}</option>
              <option value="rowing">{t("rowing")}</option>
              <option value="golf">{t("golf")}</option>
              <option value="skiing">{t("skiing")}</option>
              <option value="snowboarding">{t("snowboarding")}</option>
              <option value="surfing">{t("surfing")}</option>
              <option value="climbing">{t("climbing")}</option>
              <option value="other">{t("other")}</option>
            </select>
            {formData.sportactivity === "other" && (
              <input
                type="text"
                name="sportactivityOther"
                placeholder={t("specifySportActivity")}
                value={formData.sportactivityOther}
                onChange={handleChange}
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300 mt-2"
              />
            )}
          </motion.div>

          {/* Preferred Foods */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("preferredFoods")}
            </label>
            <input
              type="text"
              name="preferredFoods"
              value={formData.preferredFoods}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Un Preferred Foods */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("unpreferredFoods")}
            </label>
            <input
              type="text"
              name="unpreferredFoods"
              value={formData.unpreferredFoods}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Food Allergies */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("foodAllergies")}
            </label>
            <input
              type="text"
              name="foodallergies"
              value={formData.foodallergies}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Diet History || past experience */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("pastexperience")}
            </label>
            <input
              type="text"
              name="pastexperience"
              value={formData.pastexperience}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Medical History */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("medicalHistory")}
            </label>
            <input
              type="text"
              name="medicalhistory"
              value={formData.medicalhistory}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Religion */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("religionDietaryRestrictions")}
            </label>
            <select
              name="religion"
              value={formData.religion}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            >
              <option value="">{t("selectReligionOrPattern")}</option>
              <option value="best not to answer">{t("bestnottoanswer")}</option>
              <option value="islam">{t("islam")}</option>
              <option value="christianity">{t("christianity")}</option>
              <option value="other">{t("other")}</option>
            </select>
            {formData.religion === "other" && (
              <input
                type="text"
                name="religionOther"
                placeholder={t("specifyReligionOrPattern")}
                value={formData.religionOther}
                onChange={handleChange}
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300 mt-2"
              />
            )}
          </motion.div>

          {/* 3-Day Food Recall */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-4 p-4 bg-gray-50 rounded-lg"
          >
            <h3 className="font-semibold text-gray-700 mb-2">
              {t("threeDayFoodRecall")}
            </h3>
            <p className="text-sm text-gray-600 mb-3">
              {t("foodRecallDescription")}
            </p>
            
            <div className="space-y-3">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  {t("day1")} ({t("weekday")})
                </label>
                <textarea
                  name="foodRecallDay1"
                  value={formData.foodRecallDay1}
                  onChange={handleChange}
                  placeholder={t("describeMealsSnacks")}
                  rows="2"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 transition-all duration-300"
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  {t("day2")} ({t("weekday")})
                </label>
                <textarea
                  name="foodRecallDay2"
                  value={formData.foodRecallDay2}
                  onChange={handleChange}
                  placeholder={t("describeMealsSnacks")}
                  rows="2"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 transition-all duration-300"
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  {t("day3")} ({t("weekendHoliday")})
                </label>
                <textarea
                  name="foodRecallDay3"
                  value={formData.foodRecallDay3}
                  onChange={handleChange}
                  placeholder={t("describeMealsSnacks")}
                  rows="2"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 transition-all duration-300"
                />
              </div>
            </div>
          </motion.div>

          {/* Budget */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("budget")}
            </label>
            <input
              type="text"
              name="budget"
              value={formData.budget}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Extra Notes */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <label className="block font-semibold text-gray-700">
              {t("extraNotes")}
            </label>
            <input
              type="text"
              name="extranotes"
              value={formData.extranotes}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* InBody File Upload */}
          <motion.div className="space-y-2">
            <label className="block font-semibold text-gray-700">
              {t("uploadInBodyAnalysis")}
            </label>
            <input
              type="file"
              name="inbodyFile"
              accept=".pdf,.jpg,.png"
              onChange={handleFileChange}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-4 focus:ring-teal-500 transition-all duration-300"
            />
          </motion.div>

          {/* Submit Button */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="space-y-2"
          >
            <button
              className="w-full p-4 bg-teal-600 text-white font-bold rounded-lg transition-all duration-300 hover:bg-teal-700 transform hover:scale-105 disabled:bg-gray-300"
              type="submit"
              disabled={
                loading ||
                !formData.language ||
                !formData.weight ||
                !formData.height ||
                !formData.age ||
                !formData.gender ||
                (formData.inbodyFile && !formData.fitnessGoals)
              }
              style={{ display: "flex", justifyContent: "center" }}
            >
              {loading ? (
                <div className="lds-ring text-center">
                  <div></div>
                  <div></div>
                  <div></div>
                  <div></div>
                </div>
              ) : (
                t("generateDietPlan2")
              )}
            </button>
          </motion.div>
        </form>
      </div>
    </div>
  );
}